typedef struct Container { void* data; } Container;
typedef struct Payload { int magic; } Payload;

// Type Casting for Generic Storage
Payload* p = malloc(sizeof(Payload));
Container c = { .data = p };

// Retrieval (Explicit Downcast)
Payload* retrieved = (Payload*)c.data;

// Memory Reinterpretation (Strict Aliasing Exemption)
int i = 0x1A2B3C4D;
unsigned char* byte_ptr = (unsigned char*)&i;

// Accessing individual bytes
byte_ptr[0] = 0xFF; // Modify LSB

// Type-punning via Union (Safe alternative to simple casting)
union {
    int ival;
    float fval;
} punner;

punner.ival = 100;
float f = punner.fval; // Access memory as float
